<template>
    <div class="lmui-lookup-field" :style="{width:width};" @keyup.esc="resetState">
        <div class="lookup-input" :class="{'disabled': isDisabled}" style="position:relative;">
            <input style="width:100%;padding-left:10px;" @keyup.stop="onInputKeyup" @click="onInputFocus" @blur="onInputBlur" v-model="searchQuery"
            placeholder="{{placeholder}}" :disabled=isDisabled>
            <svg class="icons26 icon-gray lmui-icon-lookup" style="position:absolute;right:4px;top:4px;">
                <use xlink:href="#icon-lookup-26"></use>
            </svg>
            <div class="glob-tip" :class="{'expanded': isGlobExpanded}" v-if="isGlob && isGlobDongleVisible" @click="toggleGlobTip">
                <span class="glob-tip-label">This field can match on glob expressions.</span>
                <svg class="icons18 icon-white lmui-icon-regex">
                    <use xlink:href="#icon-regex"></use>
                </svg>
            </div>
        </div>
        <div class="lookup-menu" v-show="state != 0">
            <div class="lookup-tip" v-show="state == 1">
                <div class="loadingcircles32" style="display:inline-block;position:absolute;top:0;right:10px;">
                    <div class="circle32-gray circle32_0{{number}}" v-for="number in [1,2,3,4,5,6,7,8]"></div>
                </div><span>Searching for suggestions...</span>
            </div>
            <div class="lookup-tip" v-show="state == 2 && displayItems.length > 0">Suggested Results</div>
            <div class="lookup-tip" v-show="state == 2 && displayItems.length == 0">No matching result found</div>
            <div class="look-up-item" :class="{hovering: $index == hoveringIndex}" v-for="item in displayItems" track-by="id" @mousedown.stop.prevent="onSelectItem" data-value="{{item | json}}"
             @mouseover="onMouseover" @mouseout="onMouseout" @keyup.enter.stop.prevent="onSelectItem">{{{item.name | lookupHighlight}}}</div>
            <div class="lookup-tip" v-show="state == 2 && parsedItems.length > displayItems.length">Keep typing to refine results</div>
        </div>
    </div>
</template>

<script>
    import Vue from 'vue';
    import utils from 'utils';
    import dom from 'dom';
    import '../common/scss/common.scss';
    import './lookup-field.scss';

    Vue.filter('lookupHighlight', function (value) {
        return value.replace(new RegExp(utils.escapeRegExp(this.searchQuery), 'ig'), '<span style="font-weight: normal">$&</span>')
    });

    export default {
        props: {
            /**
             * define the initial raw items for the autocomplete
             *
             * for lookup component, the items should always be objects,
             * if the items passed to the component are not objects, we will automatically convert it to objects
             */
            items: {
                type: [Array],
                coerce: function (arr) {
                    arr.forEach(function (item, index) {
                        if (!Vue.util.isObject(item)) {
                            arr[index] = {
                                id: String(item),
                                name: String(item)
                            };
                        } else if (!item.id) {
                            item.id = JSON.stringify(item);
                        }
                    });

                    return arr;
                },
                default: function () {
                    return [];
                }
            },
            width: {                    // define the width of the lookup, default is 100%
                coerce: function (customWidth) {
                    return Number.isInteger(Number(customWidth)) ? (customWidth + 'px') : customWidth;
                },
                type: [String, Number],
                default: '100%'
            },
            placeholder: String,        // define the placeholder for the lookup input
            resultLimits: {             // the max items displayed in the lookup dropdown
                type: [Number],
                default: 10
            },
            isDisabled: Boolean,
            isGlob: Boolean,            // define if the lookup enable the glob mode
            isGlobDongleVisible: {      // this is used to control the visibility of the dongle, even isGlob is true, the dongle can be hidden
                type: [Boolean],
                default: true
            },
            isResetQueryOnFocus: {      // define whether to keep the search query when the input got focus
                type: [Boolean],
                default: true
            },
            isEnableSelectMode: {       // enable select mode, when select some menu item, trigger the "select" event
                type: [Boolean],
                default: false
            },
            isClearQueryAfterSelect: {  // in select mode, define whether to clear the search query after select the menu item
                type: [Boolean],
                default: false
            },
            selectedItem: null,          // the selectedItem is used to track the selected item from the dropdown
            ifSetMenuWidth: false    //items menu should be set width dynamically
        },

        created () {
            if (this.selectedItem) {    // allow the user to pass a initial selectedItem to set search query
                this.searchQuery = this.selectedItem.name;
            }
        },

        data () {
            return {
                searchQuery: '',
                state: 0,               // 0: init, 1: onSearching, 2: showSearchedList,
                isGlobExpanded: false,
                hoveringIndex: -1
            }
        },

        computed: {
            /**
             *  the parsed items are total items, including the inserted glob string item.
             */
            parsedItems: function () {
                var globItemQuery = this.searchQuery.trim() + (/\*$/.test(this.searchQuery) ? '' : '*');
                var globItem = {
                    id: globItemQuery,
                    name: globItemQuery
                };

                return this.isGlob ? [globItem].concat(this.items) : this.items.concat();
            },

            /**
             * the display items are only for displaying, it will be limited by the resultLimits
             */
            displayItems: function () {
                return this.parsedItems.slice(0, this.resultLimits);
            }
        },

        methods: {
            onInputKeyup (e) {
                switch(e.keyCode) {
                    case 13: // enter
                        this.onInputEnter();
                        break;
                    case 27: // esc
                        this.resetState();
                        break;
                    case 40: // up or down arrow
                    case 38:
                        this.doKeyboardNav(e.keyCode);
                        break;
                    case 9:  // check the tab key to do the focus event
                        this.onInputFocus();
                        break;
                    default:
                        this.doLookup(this.searchQuery);
                }
            },

            /**
             * call this function if the input got focus or get clicked
             * why don't directly listen to the "focus" event?
             * because we also need to listen to the "click" event, and the "click" event will cause "focus" event,
             * that will make the onInputFocus get called duplicatedly
             */
            onInputFocus () {
                this.hoveringIndex = -1;
                this.doLookup(this.isResetQueryOnFocus ? '' : this.searchQuery);
            },

            doLookup : Vue.util.debounce(function (query) {
                //DEV-22662, if put the logic in attached method, there was a bug in SVG icon of IE
                if(!this.ifSetMenuWidth){
                    //dynamic set lookup menu width
                    dom.setElWidth(this.$el.querySelector('.lookup-menu'), dom.getElWidth(this.$el) - 30);
                    this.ifSetMenuWidth = true;
                }

                this.state = 1;
                this._initialQuery = query;
                this.$emit('lookup', query);
            }, 200),

            doKeyboardNav (keyCode) {
                if (this.displayItems.length > 0) {
                    if (keyCode == 38) {         // up arrow
                        if (this.hoveringIndex < 0) {
                            this.hoveringIndex = this.displayItems.length - 1;
                        } else {
                            --this.hoveringIndex;
                        }
                    } else if (keyCode == 40) {  // down arrow
                        ++this.hoveringIndex;

                        if (this.hoveringIndex >= this.displayItems.length) {
                            this.hoveringIndex = -1;
                        }
                    }

                    if (this.hoveringIndex > -1) {
                        this.searchQuery = this.displayItems[this.hoveringIndex].name;
                    } else if (this.hoveringIndex == -1) {
                        this.searchQuery = this._initialQuery;
                    }
                }
            },

            onSelectItem (e) {
                // update the selected item when the user select from the dropdown
                this.selectedItem = utils.parseJSON(dom.getElData(e.currentTarget, 'value'));

                // do not validate when the user select the item from the dropdown
                clearTimeout(this.blurTimer);

                this.selectItem(this.selectedItem);
            },

            selectItem (item) {
                var selectedItem = item;

                if (!Vue.util.isObject(selectedItem)) {
                    var searchQuery = String(item);
                    selectedItem = {
                        id: searchQuery,
                        name: searchQuery
                    };
                }

                this.searchQuery = selectedItem.name;
                this.resetState();

                if (this.isEnableSelectMode) {
                    this.$emit('select', selectedItem);

                    if (this.isClearQueryAfterSelect) {
                        this.searchQuery = '';

                        // need clear the selectedItem when clear the search query
                        this.selectedItem = null;
                    }
                }
            },

            validateSelectedItem (isQueryRequired) {
                return (this.searchQuery && this.selectedItem && this.selectedItem.name == this.searchQuery) ||
                        (!isQueryRequired && !this.selectedItem && !this.searchQuery);
            },

            resetState () {
                this.items = [];
                this.hoveringIndex = -1;
                this._initialQuery = '';
                this.state = 0;
            },

            onMouseover (e) {
                var curItem = utils.parseJSON(dom.getElData(e.currentTarget,'value'));
                this.hoveringIndex = this.displayItems.findIndex(function (item) {
                    return item.id == curItem.id && item.name == curItem.name;
                });
            },

            onMouseout (e) {
                this.hoveringIndex = -1;
            },

            toggleGlobTip () {
                this.isGlobExpanded = !this.isGlobExpanded;
            },

            onInputEnter () {
                var query = this.searchQuery.trim();

                if (query) {
                    if (this.hoveringIndex > -1) {
                        this.selectedItem = this.displayItems[this.hoveringIndex];
                        this.selectItem(this.selectedItem);
                    } else {
                        this.selectItem({
                            id: query,
                            name: query
                        });
                    }
                }
            },

            onInputBlur () {
                var me = this;

                // if the selectItem is executed after the blur event, then we need have a chance to cancel the blur events
                this.blurTimer = setTimeout(function() {
                    me.resetState();
                    me.$emit('validate', me.searchQuery);
                }, 100);
            }
        },

        watch: {
            'items': function (val, oldVal) {
                if (this.state == 1) {
                    this.state = 2;
                }
            }
        }
    }
</script>



